use std::fs;

pub struct Order {
    pub id: u32,
    pub customer: String,
    pub amount: f64,
}

pub fn load(path: &str) -> Vec<Order> {
    let text = fs::read_to_string(path).unwrap();
    text.lines()
        .skip(1)
        .map(|line| {
            let cols: Vec<&str> = line.split(',').collect();
            Order {
                id: cols[0].parse().unwrap(),
                customer: cols[1].to_string(),
                amount: cols[2].parse().unwrap(),
            }
        })
        .collect()
}

